   column until its text wraps to five lines and scrolling the panel, scroll: the
   groups exist so a reader can go to the one question they came for. */
/* The grid's floor, and it is a floor rather than a fit: a table this wide would
   otherwise collapse its columns into unreadable slivers before the panel decides
   to scroll. Folding Stars into the member cell, CI into a dot and the last-commit
   date into a 90-day graph is what let this come down from 1500. */
#fleet { min-width: 1090px; }
#roster { min-width: 1080px; }
/* Health is prose and needs room to be one line per reason; every other column is a
   number or a chip and can stay narrow. */
/* The identity cell holds whole sentences on the rare row that has a reason left to
   spell out, so it needs room to wrap rather than to stretch the grid. */
#fleet td.member-cell { min-width: 210px; max-width: 280px; }

/* The benefits block leads the page, so it is allowed one step more presence than
   the status tiles that follow it — and the delta line is the point of each tile. */
.tiles.benefits .tile { border-color: var(--rule); }
.tiles.benefits .v { font-size: 28px; }
.sub.delta.good { color: var(--good); }
.sub.delta.bad { color: var(--serious); }

/* --- activity charts --- */
.charts { display: grid; grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
          gap: 10px; }
.chart-card { background: var(--surface); border: 1px solid var(--border);
              border-radius: 10px; padding: 12px 14px; display: flex; flex-direction: column; gap: 8px; }
.chart-card .k { font-size: 12px; color: var(--ink-2); }
.chart-wrap { display: flex; flex-direction: column; gap: 5px; }
svg.chart { width: 100%; height: 84px; display: block; }
svg.chart rect.col { opacity: .92; }
svg.chart rect.col:hover { opacity: 1; }
.chart-axis { display: flex; justify-content: space-between; gap: 8px; }
.movement .v { font-size: 25px; line-height: 1.15; }

/* The digest is prose, so it is set as prose — the only place on this page that is.
   Its own headings come from the file and must not inherit the panel headings'
   uppercase tracking, which would shout a sentence. */
.chart-card.digest h3 { font-size: 14px; margin: 0; letter-spacing: 0; text-transform: none; }
.chart-card.digest h4 { font-size: 12px; margin: 6px 0 0; color: var(--ink-2); font-weight: 600;
                        letter-spacing: 0; text-transform: none; }
.chart-card.digest p { margin: 0; color: var(--ink-2); }
.chart-card.digest ul.digest-items { margin: 0; padding-left: 18px; color: var(--ink-2); }
.chart-card.digest ul.digest-items li { margin-bottom: 6px; }
.movement .k { font-size: 12px; color: var(--ink-2); margin: 2px 0 6px; }

/* The work table's view switcher. A segmented control rather than a dropdown: there
   are three, they are always all available, and each carries its own count so the
   reader knows what a click is offering before making it. */
.views { display: flex; gap: 6px; margin-bottom: 10px; flex-wrap: wrap; }
button.view-tab { font-size: 12px; padding: 4px 11px; border-radius: 999px;
                  color: var(--ink-2); text-transform: capitalize; }
button.view-tab.on { border-color: var(--ink-2); color: var(--ink); font-weight: 600; }
/* The rows animate from where they were to where they are now, which needs each row
   to be its own containing block for the transform. */
#work tbody tr { will-change: transform; }
#work { min-width: 900px; }

/* Two series, two scales. The right-hand axis label sits at the right so it reads
   against the axis it belongs to. */
.chart-axis .axis.right { text-align: right; }
.series-line { fill: none; stroke-width: 1.5; vector-effect: non-scaling-stroke;
               stroke-linejoin: round; stroke-linecap: round; }
svg.chart.dual { height: 96px; }
/* The growth chart earns the full width: a month at daily resolution squeezed into a
   third of the row is a smear. */
.chart-card.wide { grid-column: 1 / -1; }

tr.pending-row td { color: var(--muted); }
#fleet-progress { font-size: 12px; color: var(--muted); margin: 0 0 10px; }
.pill { font-size: 12px; border: 1px solid var(--border); border-radius: 999px;
        padding: 2px 9px; color: var(--ink-2); background: var(--surface); }
.pill.warn-pill { border-color: var(--serious); color: var(--serious); }
.pill.stop-pill { border-color: var(--critical); color: var(--critical); }
.notice { border-left: 3px solid var(--serious); background: var(--surface);
          padding: 10px 14px; border-radius: 0 8px 8px 0; margin-bottom: 14px; color: var(--ink-2); }
.notice b { color: var(--ink); }

.empty { padding: 22px; text-align: center; color: var(--muted); }
.err { border-left: 3px solid var(--critical); background: var(--surface);
       padding: 10px 14px; border-radius: 0 8px 8px 0; margin-bottom: 14px; }
/* The explainer rides in the topbar and opens OVER the page. It answers a question
   you have once — "what is this thing doing with my credential" — and as a block in
   the flow it pushed the content it explains down the screen on every load after
   that one. `position: fixed` rather than absolute: the topbar is sticky, and an
   absolutely-positioned panel inside it is clipped by the bar's own height. */
details.setup { position: relative; }
details.setup > summary { cursor: pointer; list-style: none; font-size: 12px;
                border: 1px solid var(--border); border-radius: 999px;
                padding: 2px 9px; color: var(--ink-2); background: var(--surface); }
details.setup > summary::-webkit-details-marker { display: none; }
details.setup > summary:hover { border-color: var(--ink-2); color: var(--ink); }
details.setup[open] > summary { border-color: var(--ink-2); color: var(--ink); }
.setup-body { position: fixed; top: 52px; right: 20px; z-index: 20; width: min(480px, calc(100vw - 40px));
              max-height: calc(100vh - 72px); overflow: auto;
              background: var(--surface); border: 1px solid var(--border);
              border-radius: 10px; padding: 4px 16px 12px;
              box-shadow: 0 12px 32px color-mix(in srgb, var(--ink) 18%, transparent); }
.setup-body p, .setup-body li { color: var(--ink-2); }
.setup-body p:last-child { margin-bottom: 4px; }

/* The member cell: the star mark ahead of the name, so `Stars` costs no column. */
.member { display: flex; gap: 9px; align-items: baseline; }
.stars { text-align: center; flex: none; min-width: 26px; }
.stars .glyph { font-size: 11px; line-height: 1; color: var(--s-yellow); }
.stars .n { font-size: 12px; color: var(--ink-2); }

/* CI as a dot with its age under it, beside the name rather than in a column. */
.ci-mark { text-align: center; flex: none; min-width: 30px; }
.ci-mark .dot { display: inline-block; width: 9px; height: 9px; border-radius: 50%;
                background: var(--muted); }
.ci-mark .dot.ok { background: var(--good); }
.ci-mark .dot.critical { background: var(--critical); }
.ci-mark .dot.info { background: var(--muted); }
.ci-mark .sub { margin-top: 3px; }

