export const packBadge = (pack) => {
  let h = 0;
  for (const ch of pack) h = (h * 31 + ch.charCodeAt(0)) % 997;
  return el('span', {
    className: 'pack-badge',
    style: `background:${PACK_HUES[h % PACK_HUES.length]}`,
    textContent: (pack.replace(/^claudinite-/, '')[0] ?? '?').toUpperCase(),
    'aria-hidden': 'true',
