});

// PROVED AGAINST THE REAL TREE, not only against a clean fixture: a fixture spells the
// same gap the check has, so only the repo's own sources can disagree with it. And the
// scope must be non-empty — a pattern left behind by a layout change matches nothing,
// reads as live, and catches nothing.
test('the check is silent on the real corpus, and its scope is not empty', () => {
  const files = execFileSync('git', ['ls-files'], { encoding: 'utf8', cwd: new URL('../..', import.meta.url).pathname })
    .split('\n').filter(Boolean);
  const tree = Object.fromEntries(files.map((f) => [f, null]));
  const real = {
    allFiles: files,
    read: (f) => (f in tree
      ? execFileSync('git', ['show', `HEAD:${f}`], { encoding: 'utf8', cwd: new URL('../..', import.meta.url).pathname, stdio: ['ignore', 'pipe', 'ignore'] })
      : null),
  };
  const descriptors = files.filter((f) => /^packs\/[^/]+\/dashboard\.json$/.test(f));
  assert.ok(descriptors.length > 0, 'no pack descriptor in the tree — the check would match nothing and read as live');
  // Read from the working tree rather than HEAD, so a descriptor added in this change
  // is covered too (a brand-new file is untracked at HEAD).
  const fs = { allFiles: files, read: (f) => { try { return require('node:fs').readFileSync(new URL(`../../${f}`, import.meta.url), 'utf8'); } catch { return null; } } };
  assert.deepEqual(rule.run(fs), []);
  assert.ok(real);
});
